/**
 * constant.js
 */

/**
 * The total number of 8-bit byte values (0x00–0xFF).
 * @type {number}
 */
export const BYTE_RANGE = 256;

/**
 * Chunk size (8KB) used when processing byte arrays to avoid stack overflow.
 * @type {number}
 */
export const CHUNK_SIZE = 8 * 1024;

/**
 * Decimal radix used for numeric string conversion.
 * @type {number}
 */
export const DECI = 10;

/**
 * Hexadecimal radix used for numeric string conversion.
 * @type {number}
 */
export const HEX = 16;

/**
 * Maximum allowed Blob size (16MB).
 * @type {number}
 */
export const MAX_BLOB_SIZE = 16 * 1024 * 1024;

/**
 * Maximum recursion depth allowed for nested parsing.
 * @type {number}
 */
export const MAX_NEST = 16;

/**
 * Maximum URL length (64KB).
 * @type {number}
 */
export const MAX_URL_LENGTH = 64 * 1024;

/**
 * Length used for truncating string.
 * @type {number}
 */
export const TRUNCATE_LENGTH = 64;

/**
 * Start index used to extract the type name from Object.prototype.toString().
 * (e.g. removes "[object " prefix)
 * @type {number}
 */
export const TYPE_FROM = 8;

/**
 * End index used to extract the type name from Object.prototype.toString().
 * (e.g. removes trailing "]")
 * @type {number}
 */
export const TYPE_TO = -1;

/**
 * The dummy base URL.
 * @type {string}
 */
export const DUMMY_BASE = 'http://dummy.local';

/**
 * The default sanitization options.
 * @type {import('./sanitize.js').InternalSanitizeOptions}
 */
export const DEFAULT_OPTS = {
  allow: Object.freeze([]),
  deny: Object.freeze([]),
  only: null,
  allowRelative: false,
  debug: false,
  revokeObjectURL: false,
  maxBlobSize: MAX_BLOB_SIZE,
  maxLength: MAX_URL_LENGTH,
  schemes: new Set()
};
